import com.comsol.model.*;import com.comsol.model.util.*;import java.io.*;import java.util.*;
public class ReferenceFunctionAudit20261017{public static void main(String[] a)throws Exception{ModelUtil.initStandalone(false);Model m=ModelUtil.load("FunctionAudit",a[0]);PrintWriter p=new PrintWriter(a[1],"UTF-8");for(String t:m.func().tags()){p.println("FUNCTION|"+t+"|"+m.func(t).getType());for(String k:m.func(t).properties())try{p.println(k+"="+Arrays.toString(m.func(t).getStringArray(k)));}catch(Throwable e){try{p.println(k+"="+m.func(t).getString(k));}catch(Throwable ee){}}}p.close();System.exit(0);}}
